    // Invalid bracket combinations
    console.log('Invalid mismatched:', isValidBrackets('(]') === false);
    console.log('Invalid wrong order:', isValidBrackets('([)]') === false);
    console.log('Invalid extra closing:', isValidBrackets('())') === false);
    console.log('Invalid extra opening:', isValidBrackets('(()') === false);
    console.log('Invalid unclosed:', isValidBrackets('{[}') === false);

    // Deeply nested brackets
    console.log('Deeply valid:', isValidBrackets('({[({[()]})]})') === true);
    console.log('Deeply invalid:', isValidBrackets('({[({[()]})]})}') === false);

    // Non-string inputs
    console.log('Null input:', isValidBrackets(null) === false);
    console.log('Number input:', isValidBrackets(123) === false);
    console.log('Object input:', isValidBrackets({}) === false);
    console.log('Array input:', isValidBrackets([]) === false);

    // Mixed content
    console.log('Mixed valid:', isValidBrackets('a(b[c]d{e}f)g') === true);
    console.log('Mixed invalid:', isValidBrackets('a(b[c)d{e}f]g') === false);
}

// Run tests
testIsValidBrackets();
```

**Complexity Analysis:**

1. **Time Complexity: O(n)**
   - We iterate through the string exactly once
   - Each operation inside the loop (checking brackets, pushing/popping from stack) is O(1)
   - Therefore, total time is proportional to the length of the string

2. **Space Complexity: O(n) worst-case**
   - The stack could potentially store all characters in the string if they're all opening brackets
   - For example, with input '((((((((', the stack will grow to size n
   - In balanced cases, the stack size will be much smaller, but worst-case is O(n)

**Implementation Details:**

1. **Non-bracket characters:** As specified, these are ignored. They don't affect the validation logic.

2. **Input validation:** The function explicitly checks if the input is a string. Non-string inputs (null, numbers, objects, etc.) return false.

3. **LIFO stack logic:**
   - Opening brackets are pushed onto the stack
   - When a closing bracket is encountered, the stack is popped to get the most recent opening bracket
   - If they don't match (e.g., '[' with ')'), it's invalid
   - If a closing bracket is encountered when the stack is empty, it's invalid

4. **Final validation:** After processing all characters, if the stack is empty, all brackets were properly closed. If not, there are unclosed brackets.

This implementation meets all the specified requirements and handles all the edge cases mentioned in the tests.

I'll implement both iterative and recursive variants of binary search that return the first occurrence of a target in a sorted array.

```js
/**
 * Performs a binary search on a sorted array to find the first occurrence of the target.
 * 
 * @param {Array<number>} sorted - The sorted array to search in (ascending order)
 * @param {number} target - The value to search for
 * @returns {number} The index of the first occurrence of the target, or -1 if not found
 * 
 * Requirements:
 * - Time complexity: O(log n)
 * - Space complexity: O(1)
 * - Returns the first occurrence when duplicates exist
 * - Does not mutate the input array
 * - Uses safe midpoint computation: left + Math.floor((right - left) / 2)
 * - Assumes the input array is sorted in ascending order
 * - Returns -1 if target is not found in the array
 */
function binarySearch(sorted, target) {
  if (!sorted || sorted.length === 0) return -1;

  let left = 0;
  let right = sorted.length - 1;
  let result = -1;

  while (left <= right) {
    const mid = left + Math.floor((right - left) / 2);

    if (sorted[mid] === target) {
      result = mid;
      right = mid - 1; // Continue searching left half for earlier occurrence
    } else if (sorted[mid] < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return result;
}

/**
 * Recursive binary search that finds the first occurrence of the target.
 * 
 * @param {Array<number>} sorted - The sorted array to search in (ascending order)
 * @param {number} target - The value to search for
 * @returns {number} The index of the first occurrence of the target, or -1 if not found
 * 
 * Requirements:
 * - Time complexity: O(log n)
 * - Space complexity: O(log n) due to recursion stack
 * - Returns the first occurrence when duplicates exist
 * - Does not mutate the input array
 * - Uses safe midpoint computation: left + Math.floor((right - left) / 2)
 * - Safe for null/undefined input
 * - Assumes the input array is sorted in ascending order
 * - Returns -1 if target is not found in the array
 */
function binarySearchRecursive(sorted, target, left = 0, right = null) {
  // Handle null/undefined input
  if (!sorted) return -1;

  // Initialize right if not provided (first call)
  if (right === null) {
    right = sorted.length - 1;
  }

  // Base case: search space is exhausted
  if (left > right) return -1;

  const mid = left + Math.floor((right - left) / 2);

  if (sorted[mid] === target) {
    // Check if this is the first occurrence
    if (mid === 0 || sorted[mid - 1] < target) {
      return mid;
    }
    // Continue searching left half for earlier occurrence
    return binarySearchRecursive(sorted, target, left, mid - 1);
  } else if (sorted[mid] < target) {
    return binarySearchRecursive(sorted, target, mid + 1, right);
  } else {
    return binarySearchRecursive(sorted, target, left, mid - 1);
  }
}
```

Implementation details:

1. **Iterative binarySearch**:
   - Uses a while loop to narrow down the search space
   - When the target is found, it continues searching the left half to find the first occurrence
   - Maintains O(log n) time complexity and O(1) space complexity
   - Returns -1 if the target is not found

2. **Recursive binarySearchRecursive**:
   - Uses recursion to implement the binary search
   - When the target is found, it checks if it's the first occurrence by verifying the previous element
   - If not the first occurrence, it continues searching the left half
   - Has O(log n) time complexity but O(log n) space complexity due to the recursion stack
   - Includes validation for null/undefined input at the beginning of the function
   - Uses default parameters for left and right to simplify initial calls

Both implementations:
- Use the safe midpoint computation: left + Math.floor((right - left) / 2)
- Assume the input array is sorted in ascending order
- Return -1 if the target is not found
- Never mutate the input array
- Handle duplicates by finding the first occurrence
